io :: import "std/io"

BinaryOp :: fn(i32, i32) i32

add :: fn(a: i32, b: i32) i32 {
    ret a + b
}

apply :: fn(op: BinaryOp, a: i32, b: i32) i32 {
    ret op(a, b)
}

main :: fn() {
    raw: fn(i32, i32) i32 = add
    callback: BinaryOp = add
    io.println("{} {}", raw(8, 3), apply(callback, 8, 3))
}

